target.css:
:root {
  --ink: #263b35;
  --paper: #fffdf7;
  --cream: #f4ead8;
  --moss: #73865d;
  --coral: #cf684f;
  --line: #d9d0bf;
}

.arrangement-card {
  width: 480px;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px;
  background: var(--ink);
  color: var(--paper);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
}

.status {
  padding: 5px 9px;
  background: var(--coral);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.session-details {
  display: grid;
  grid-template-columns: 1fr 138px;
  gap: 16px;
  padding: 16px 18px;
}

.stem-plan h2 {
  margin: 0 0 8px;
  color: var(--moss);
  font-size: 12px;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.stem-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.stem-list li {
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}

.stem-list strong {
  color: var(--moss);
  font-size: 12px;
}

.seat-card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 12px;
  background: var(--cream);
  border-radius: 12px;
  color: var(--ink);
}

.seat-label {
  color: var(--moss);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.seat-card strong {
  font-size: 20px;
  line-height: 1.1;
}

.seat-card span:last-child {
  font-size: 12px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  font-size: 13px;
  line-height: 1.2;
}

.card-footer p span {
  color: var(--moss);
}

button {
  padding: 7px 10px;
  background: var(--paper);
  border: 1px solid var(--moss);
  border-radius: 8px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

